function _renderProposalMarkerLinks(layouts) {
  var layer = _ensureProposalMarkerLayer();
  if (!layer) return;
  if (!layer._wheelForwardBound) {
    layer.addEventListener('wheel', _forwardProposalMarkerWheel, { capture: true, passive: false });
    layer._wheelForwardBound = true;
  }
  if (!layer._hoverForwardBound) {
    layer.addEventListener('mousemove', _forwardProposalMarkerHoverEvent, { capture: true, passive: true });
    layer.addEventListener('pointermove', _forwardProposalMarkerHoverEvent, { capture: true, passive: true });
    layer._hoverForwardBound = true;
  }
  if (!layer._clickBound) {
    layer.addEventListener('click', function(e) {
      var btn = e.target.closest('.proposal-marker-link[data-proposal-key]');
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      _scrollToProposalTimelineEvent(btn.dataset.proposalKey);
    });
    layer._clickBound = true;
  }
  layer._bound = true;
  if (!layouts || layouts.length === 0) {
    if (layer._html) layer.innerHTML = '';
    layer._html = '';
    layer.style.display = 'none';
    return;
  }
  var html = layouts.map(function(layout) {
    var iconSrc = _proposalIconSrc(layout.outcome);
    var dataAttrs = layout.proposalKey ? ' data-proposal-key="' + _esc(layout.proposalKey) + '"' : '';
    var iconHtml = _proposalEventIconHtml(layout.kind, layout.outcome, iconSrc);
    return '<button type="button" class="proposal-marker-link"' + dataAttrs + ' ' +
      'aria-label="' + _esc(layout.title) + '" title="' + _esc(layout.title) + '" style="' +
      'left:' + Math.round(layout.left) + 'px;top:' + Math.round(layout.top) + 'px;' +
      'width:' + Math.round(layout.width) + 'px;height:' + Math.round(layout.height) + 'px">' +
      iconHtml + '</button>';
  }).join('');
  layer.style.display = 'block';
  if (layer._html !== html) {
    layer.innerHTML = html;
    layer._html = html;
  }
}

