function _alignTrackedNavLaunchPoint(navPoints, pricePoints, icoPrice) {
  if (!navPoints || navPoints.length === 0 || !pricePoints || pricePoints.length === 0 || !(icoPrice > 0)) {
    return navPoints || [];
  }
  var launchTime = Number(pricePoints[0] && pricePoints[0].time);
  if (!(launchTime > 0)) return navPoints;
  if (navPoints[0].time > launchTime) {
    return [{ time: launchTime, value: icoPrice }].concat(navPoints);
  }
  if (navPoints[0].time === launchTime && navPoints[0].value !== icoPrice) {
    // Some launches have a documented TGE NAV that differs from the listing
    // price. Keep that evidence instead of forcing NAV to equal ICO price.
    if (navPoints[0].syntheticPreTgeNav === true) return navPoints;
    if (navPoints.length === 1 && CFG && CFG.nav > 0 && Math.abs(navPoints[0].value - CFG.nav) / CFG.nav < 0.01) {
      return _padLineSeriesForSinglePoint(navPoints, (typeof _chartTF !== 'undefined' && _chartTF) ? _chartTF : '1D', null, icoPrice);
    }
    var aligned = navPoints.slice();
    aligned[0] = { time: launchTime, value: icoPrice };
    return aligned;
  }
  return navPoints;
}

function _padLineSeriesForSinglePoint(points, tf, preferredTime, preferredValue) {
  if (!points || points.length !== 1) return points || [];
  var only = points[0];
  if (!only || !isFinite(only.time) || !isFinite(only.value)) return points;
  var anchorTime = _singlePointSeriesAnchorTime(only.time, tf, preferredTime);
  var anchorValue = _singlePointSeriesAnchorValue(only.value, preferredValue);
  if (!isFinite(anchorValue)) return points;
  if (!isFinite(anchorTime) || anchorTime <= 0 || anchorTime >= only.time) return points;
  return [{ time: anchorTime, value: anchorValue }].concat(points);
}

function _padCandleSeriesForSinglePoint(candles, tf, preferredTime) {
  if (!candles || candles.length !== 1) return candles || [];
  var only = candles[0];
  if (!only || !isFinite(only.time)) return candles;
  var anchorTime = _singlePointSeriesAnchorTime(only.time, tf, preferredTime);
  if (!isFinite(anchorTime) || anchorTime <= 0 || anchorTime >= only.time) return candles;
  var close = only.close != null ? +only.close : +(only.price || 0);
  var open = only.open != null ? +only.open : close;
  var high = only.high != null ? +only.high : Math.max(open, close);
  var low = only.low != null ? +only.low : Math.min(open, close);
  return [{
    time: anchorTime,
    open: open,
    high: high,
    low: low,
    close: close,
    price: close
  }].concat(candles);
}

function _padVolumeSeriesForSinglePoint(points, tf, preferredTime) {
  if (!points || points.length !== 1) return points || [];
  var only = points[0];
  if (!only || !isFinite(only.time)) return points;
  var anchorTime = _singlePointSeriesAnchorTime(only.time, tf, preferredTime);
  if (!isFinite(anchorTime) || anchorTime <= 0 || anchorTime >= only.time) return points;
  return [{
    time: anchorTime,
    value: 0,
    color: only.color || 'rgba(100,140,170,0.25)'
  }].concat(points);
}

