  if (!(CFG.embedMonthlySpendingLimitUsdc >= 0) || !isFinite(CFG.embedMonthlySpendingLimitUsdc)) {
    CFG.embedMonthlySpendingLimitUsdc = null;
  }
  CFG.embedNavProjection = nav > 0 ? _normalizeEmbedNavProjection(payload, nav) : null;
