function _clearPnavCheckpointLines() {
  for (var i = 0; i < _lwPnavCheckpointLines.length; i++) {
    var checkpoint = _lwPnavCheckpointLines[i];
    try {
      if (checkpoint && checkpoint.line && checkpoint.host) {
        checkpoint.host.removePriceLine(checkpoint.line);
      }
    } catch(e) {}
  }
  _lwPnavCheckpointLines = [];
  _lwPnavLine = null;
  _lwPnavLineHost = null;
}

function _projectTreasuryAfterScheduledWithdrawals(treasuryValue, withdrawalValue, withdrawalCount) {
  var remaining = Number(treasuryValue) || 0;
  var withdrawal = Number(withdrawalValue) || 0;
  var count = Math.max(0, Math.floor(Number(withdrawalCount) || 0));
  if (!(remaining > 0) || !(withdrawal > 0)) return Math.max(remaining, 0);
  for (var i = 0; i < count; i++) {
    if (!(remaining > withdrawal)) break;
    remaining -= withdrawal;
  }
  return remaining;
}

function _pnavCheckpointValues(navSnapshot, monthlyBurn, multiplier) {
  var treasury = Number(navSnapshot && navSnapshot.treasuryUSDC) || 0;
  var supply = Number(navSnapshot && navSnapshot.supply && navSnapshot.supply.effective) || 0;
  var burn = Number(monthlyBurn) || 0;
  var mult = Number(multiplier);
  if (!isFinite(mult) || !(mult > 0)) mult = 1;
  if (!(treasury > 0) || !(supply > 1) || !(burn > 0)) return [];
  return _PNAV_CHECKPOINT_MONTHS.map(function(month) {
    return {
      month: month,
      value: _projectTreasuryAfterScheduledWithdrawals(treasury, burn, month) / supply * mult,
    };
  });
}

function _createPnavCheckpointLines(host, navSnapshot, monthlyBurn, multiplier) {
  _clearPnavCheckpointLines();
  if (!host) return [];
  var values = _pnavCheckpointValues(navSnapshot, monthlyBurn, multiplier);
  for (var i = 0; i < values.length; i++) {
    var checkpoint = values[i];
    try {
      var line = host.createPriceLine({
        price: checkpoint.value,
        color: '#ffcc00',
        lineWidth: 1,
        lineStyle: LightweightCharts.LineStyle.SparseDotted,
        lineVisible: true,
        axisLabelVisible: true,
        axisLabelTextColor: '#111111',
        title: '',
      });
      _lwPnavCheckpointLines.push({
        month: checkpoint.month,
        line: line,
        host: host,
      });
    } catch(e) {}
  }
  var terminal = _lwPnavCheckpointLines[_lwPnavCheckpointLines.length - 1] || null;
  _lwPnavLine = terminal ? terminal.line : null;
  _lwPnavLineHost = terminal ? terminal.host : null;
  return _lwPnavCheckpointLines;
}

function _updatePnavCheckpointLines(navSnapshot, monthlyBurn, multiplier, skipTerminal) {
  var values = _pnavCheckpointValues(navSnapshot, monthlyBurn, multiplier);
  for (var i = 0; i < _lwPnavCheckpointLines.length; i++) {
    var checkpoint = _lwPnavCheckpointLines[i];
    if (skipTerminal && checkpoint.month === _NAV_PROJECTION_HORIZON_MONTHS) continue;
    var next = values.find(function(value) { return value.month === checkpoint.month; });
    if (!next || !checkpoint.line) continue;
    try { checkpoint.line.applyOptions({ price: next.value }); } catch(e) {}
  }
  var terminal = _lwPnavCheckpointLines[_lwPnavCheckpointLines.length - 1] || null;
  _lwPnavLine = terminal ? terminal.line : null;
  _lwPnavLineHost = terminal ? terminal.host : null;
}

function _activeNavAxisPrice(fallbackPrice) {
  var fallback = Number(fallbackPrice);
  if (_isChartEmbed && _layerNavForecast && _lwNavForecastData && _lwNavForecastData.length > 0) {
    var projected = Number(_lwNavForecastData[_lwNavForecastData.length - 1].value);
    if (isFinite(projected) && projected >= 0) return projected;
  }
  return isFinite(fallback) ? fallback : 0;
}

