  var projectPool = _meteoraLpProjectTreasuryPool(CFG, configuredPools);
  var projectAddr = projectPool && projectPool.addr ? String(projectPool.addr).trim().toLowerCase() : '';
  var snap = isFinite(time) && time > 0 ? _lwTreasuryLookup(Number(time)) : null;
  if (snap && Array.isArray(snap.meteoraPools) && snap.meteoraPools.length > 0) {
    var active = [];
    for (var i = 0; i < snap.meteoraPools.length; i++) {
      var p = snap.meteoraPools[i] || {};
      var addr = p.poolAddress || p.pool_address || p.addr || '';
      if (!addr) continue;
      if (!(Number(p.usdc) > 0) && !(Number(p.tokens) > 0)) continue;
      var key = String(addr).trim().toLowerCase();
      var label = clean(_meteoraPoolLabelForAddr(addr));
      active.push({ addr: key, label: label });
      if (projectAddr && key === projectAddr) return clean(projectPool.label) || label || _meteoraDefaultDisplayLabel(CFG);
    }
    if (active.length === 1) return active[0].label || _meteoraDefaultDisplayLabel(CFG);
  }
