  _chartLoadedTF = null;
  _lwBsPut = null; _lwEmbedNavReference = null; _lwNavForecast = null; _lwPreIco = null; _lwNavMarkers = null; _lwPriceMarkers = null; _lwForecastMarkers = null; _lwGrowth = null;
  _lwTreasuryComponentSeries = [];
  _lwTreasuryComponentData = [];
  _lwForecastMarkerData = [];
  _lwEmbedNavReferenceData = [];
  _embedCurrentNavAnchor = null;
  _lwNavDisplayData = [];
  _lwPriceDisplayData = [];
  _navFillPrimitive = null; _monthOverlayPrimitive = null; _smoothLinePrimitive = null; _treasuryStackPrimitive = null; _navFlowMarkerPrimitive = null; _buybackDotPrimitive = null; _launchMarkerPrimitive = null;
