  var embedTransparent = _isChartEmbed
    && window.NAVGATOR.embed
    && window.NAVGATOR.embed.isTransparent();
  var is01rxChartFrame = document.documentElement.dataset['01rxChartFrame'] === 'true';
  var chartBackground = embedTransparent
