  if (futLpPair) futLpPair.textContent = (CFG.ticker || tokenKey.toUpperCase()) + '/USD';

  // Futarchy 24H vol & liquidity (from MetaDAO /api/tickers — fallback only)
  var futVolEl = document.getElementById('ta-fut-vol');
