// ── TV Candlestick Chart ──
// ── TV Candlestick Chart ── (replaced by LW v4 single instance above)
// ── Rotating change stats (1H / 24H / 7D) ──
var _chgRotatePeriods = ['1h', '24h', '7d'];
var _chgRotateIdx = 1; // start on 24h
var _chgRotatePaused = false;
var _chgRotateTimer = null;

function _chgRotateTo(period) {
  _chgRotateIdx = _chgRotatePeriods.indexOf(period);
  document.querySelectorAll('.chg-rotate-frame').forEach(function(f) {
    if (f.dataset.period === period) f.classList.add('chg-active');
    else f.classList.remove('chg-active');
  });
  document.querySelectorAll('.chg-tf').forEach(function(t) {
    if (t.dataset.period === period) t.classList.add('chg-tf-on');
    else t.classList.remove('chg-tf-on');
  });
}

function _chgRotateTick() {
  if (_chgRotatePaused) return;
  _chgRotateIdx = (_chgRotateIdx + 1) % _chgRotatePeriods.length;
  _chgRotateTo(_chgRotatePeriods[_chgRotateIdx]);
}
_chgRotateTimer = setInterval(_chgRotateTick, 5000);

// Click to select a period
document.addEventListener('click', function(e) {
  var tf = e.target.closest('.chg-tf');
  if (!tf) return;
  _chgRotateTo(tf.dataset.period);
  // Reset timer so it waits a full 5s from the click
  clearInterval(_chgRotateTimer);
  _chgRotateTimer = setInterval(_chgRotateTick, 5000);
});

// Pause rotation on hover
['chg-rotate-row', 'chg-rotate-row-pn'].forEach(function(id) {
  var row = document.getElementById(id);
  if (row) {
    row.addEventListener('mouseenter', function() { _chgRotatePaused = true; });
    row.addEventListener('mouseleave', function() { _chgRotatePaused = false; });
  }
});

