/* QUOTES & ART — random quote or artwork below addresses         */
/* ═══════════════════════════════════════════════════════════════ */
(function() {
  var _quotes = [
    { text: "If you can't feed a team with two pizzas, it's too large.", author: "Jeff Bezos" },
    { text: "If you're not embarrassed by the first version of your product, you've launched too late.", author: "Reid Hoffman" },

    { text: "Beware that, when fighting monsters, you yourself do not become a monster... for when you gaze long into the abyss, the abyss gazes also into you.", author: "Friedrich W. Nietzsche" },
    { text: "Do not go gentle into that good night.", author: "Dylan Thomas" },
    { text: "Insanity is doing the same thing over and over again and expecting different results.", author: "Albert Einstein" },
    { text: "While we wait for life, life passes.", author: "Seneca" },
    { text: "Working to create a little bit of history isn't supposed to be easy, and, well, we're finding that things are as they're supposed to be!", author: "Jeff Bezos" },
  ];
  var _artworks = [
  ];
  window._showQuoteOrArt = function() {
    var qtEl = document.getElementById('quote-text');
    var qaEl = document.getElementById('quote-author');
    var aiEl = document.getElementById('art-img');
    var acEl = document.getElementById('art-caption');
    if (!qtEl || !qaEl || !aiEl || !acEl) return;
    var totalItems = _quotes.length + _artworks.length;
    if (totalItems === 0) return;
    var pick = Math.floor(Math.random() * totalItems);
    if (pick < _quotes.length) {
      var q = _quotes[pick];
      qtEl.style.display = ''; qaEl.style.display = '';
      aiEl.style.display = 'none'; acEl.style.display = 'none';
      qtEl.textContent = '\u201c' + q.text + '\u201d';
      qaEl.textContent = '\u2014 ' + q.author;
    } else {
      var a = _artworks[pick - _quotes.length];
      qtEl.style.display = 'none'; qaEl.style.display = 'none';
      aiEl.style.display = 'block'; acEl.style.display = 'block';
      aiEl.src = a.src; aiEl.alt = a.title;
      acEl.textContent = a.title + ' \u2014 ' + a.artist;
    }
  };
  // Back-compat alias
  window._showQuote = window._showQuoteOrArt;
  window._showQuoteOrArt();
})();


/* ═══════════════════════════════════════════════════════════════ */
/* 4. KEYBOARD NAVIGATION — arrow keys through tokens              */
/* ═══════════════════════════════════════════════════════════════ */
(function() {
  document.addEventListener('keydown', function(e) {
    // Don't hijack when typing in an input
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (document.querySelector('.cmd-overlay.open')) return;

    var items = Array.from(document.querySelectorAll('.tp-item'));
    if (items.length === 0) return;
    var activeIdx = items.findIndex(function(el) { return el.classList.contains('active'); });

    if (e.key === 'ArrowDown' || e.key === 'j') {
      e.preventDefault();
      var next = activeIdx < items.length - 1 ? activeIdx + 1 : 0;
      items[next].click();
      items[next].scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'ArrowUp' || e.key === 'k') {
      e.preventDefault();
      var prev = activeIdx > 0 ? activeIdx - 1 : items.length - 1;
      items[prev].click();
      items[prev].scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Escape') {
      // Go back to landing
      if (document.body.classList.contains('is-token')) {
        window.location.href = _homePageUrl();
      }
    }
  });
})();

/* ═══════════════════════════════════════════════════════════════ */
/* 5. SECURITY HEADER BAR — Bloomberg-style token info strip       */
/* ═══════════════════════════════════════════════════════════════ */
(function() {
  window._updateSecHeader = function(cfg) {
    var bar = document.getElementById('sec-header');
    if (!bar || !cfg) return;
    var tags = [];
    tags.push('<span class="sec-tag sec-name">' + (cfg.ticker || '') + '</span>');
    tags.push('<span class="sec-tag sec-pair">' + (cfg.pair || '') + '</span>');
    if (cfg.launchpad) tags.push('<span class="sec-tag">' + _lpIcon(cfg.launchpad, 10) + ' ' + cfg.launchpad + '</span>');
    tags.push('<span class="sec-tag">Futarchy</span>');
    tags.push('<span class="sec-tag">Solana</span>');
    if (cfg.tldr) tags.push('<span class="sec-tag" style="color:#FFB000">' + cfg.tldr + '</span>');
    bar.innerHTML = tags.join('');
  };
})();
